/**
 * Wraps a control with its label, help text and error (`design/components/form-field.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/form-field.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createMemo, createUniqueId, mergeProps, onCleanup, type JSX } from 'solid-js'

import {
  Icon,
  ResolvedSlot,
  claimSlot,
  createDerived,
  removeToast,
  resolveSlot,
  scope,
  toast,
  watchEffect,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/controls/form-field.module.css'

export interface FormFieldControlProps {
  id?: string
  label?: string
  invalid?: boolean
  disabled?: boolean
  'aria-describedby'?: string
  'aria-labelledby'?: string
  'aria-required'?: boolean
}

export interface FormFieldProps {
  /**
   * Exactly one governed control: Input, Select, Checkbox or Switch.
   */
  children: JSX.Element
  /**
   * Help text. Replaced by `error` when there is one, so they never show together.
   */
  description?: string
  /**
   * When non-empty, the field is invalid.
   */
  error?: string
  /**
   * Application errors show in toasts. The generic primitive keeps its explicit inline mode.
   */
  errorPresentation?: 'inline' | 'toast'
  /**
   * Base for the derived ids. Generated when omitted.
   */
  id?: string
  label: string
  /**
   * Content at the end of the label's row, as in the login block. By convention a Link, such as
   * "Forgot your password?" beside the Password label. It is a slot rather than a `link` prop,
   * because the field does not need to know what the content *is*. The field only defines that
   * the row has two ends and the label is at the start. A row-labelled control has no label row
   * of its own, so it ignores this prop.
   */
  labelEnd?: JSX.Element
  required?: boolean
}

/** Wraps a control with its label, help text and error. */
export default function FormField(given: FormFieldProps): JSX.Element {
  const props = mergeProps(
    { errorPresentation: 'inline', required: false } as Defaults<
      FormFieldProps,
      'errorPresentation' | 'required'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const uid = createUniqueId()
    const childrenSlot = resolveSlot(
      () => props.children,
      () => ({
        id: controlId.value,
        'aria-describedby': describedBy.value,
        'aria-required': props.required ? true : undefined,
        'aria-labelledby':
          (childrenSlot.slotted().kind ?? 'field') === 'group' ? labelId.value : undefined,
        invalid: invalid.value ? true : undefined,
        label:
          (childrenSlot.slotted().kind ?? 'field') === 'row-labelled' ? props.label : undefined,
      }),
    )
    const controlId = createDerived(() => props.id ?? uid)
    const descriptionId = createDerived(() => `${controlId.value}-description`)
    const errorId = createDerived(() => `${controlId.value}-error`)
    const labelId = createDerived(() => `${controlId.value}-label`)
    const invalid = createDerived(() => props.error !== undefined && props.error !== '')
    const inline = createDerived(() => invalid.value && props.errorPresentation === 'inline')
    const noticeId = createDerived(() => `${controlId.value}-notice`)
    const showDescription = createDerived(
      () => props.description !== undefined && props.description !== '' && !invalid.value,
    )
    const describedBy = createDerived(
      () =>
        [
          inline.value ? errorId.value : undefined,
          showDescription.value ? descriptionId.value : undefined,
        ]
          .filter((value) => value !== undefined)
          .join(' ') || undefined,
    )
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran =
        invalid.value && props.errorPresentation === 'toast'
          ? toast({
              id: noticeId.value,
              title: props.label,
              description: props.error,
              tone: 'danger',
              dismissible: true,
              retained: true,
              durationMs: Number.POSITIVE_INFINITY,
            })
          : ''
      release1 = () => {
        void (ran === '' || removeToast(ran))
      }
    }
    watchEffect(
      createMemo(() => [invalid.value, props.errorPresentation, props.error, props.label]),
      effect1,
      true,
    )
    onCleanup(() => release1?.())
    return (
      <div
        class={styles.field}
        data-kind={childrenSlot.slotted().kind ?? 'field'}
        data-invalid={invalid.value ? '' : undefined}
        data-disabled={
          childrenSlot.slotted().props.disabled === true ||
          childrenSlot.slotted().props.disabled === ''
            ? ''
            : undefined
        }
        data-member="form-field"
      >
        {(childrenSlot.slotted().kind ?? 'field') !== 'row-labelled' ? (
          <ResolvedSlot of={() => props.labelEnd}>
            {(labelEndSlot) => (
              <>
                {/* labelRow */}
                <div class={styles.labelRow}>
                  {/* label */}
                  <label
                    class={styles.label}
                    id={
                      (childrenSlot.slotted().kind ?? 'field') === 'group'
                        ? labelId.value
                        : undefined
                    }
                    for={
                      (childrenSlot.slotted().kind ?? 'field') !== 'group'
                        ? controlId.value
                        : undefined
                    }
                  >
                    {props.label}
                    {props.required ? (
                      <span class={styles.required} aria-hidden="true">
                        {' *'}
                      </span>
                    ) : null}
                  </label>
                  {labelEndSlot.filled() ? (
                    <span class={styles.labelEnd}>{labelEndSlot()}</span>
                  ) : null}
                </div>
                {showDescription.value ? (
                  <p class={styles.description} id={descriptionId.value}>
                    {props.description}
                  </p>
                ) : null}
              </>
            )}
          </ResolvedSlot>
        ) : null}
        {childrenSlot()}
        {(childrenSlot.slotted().kind ?? 'field') === 'row-labelled' ? (
          showDescription.value ? (
            <p class={styles.description} id={descriptionId.value}>
              {props.description}
            </p>
          ) : null
        ) : null}
        {inline.value ? (
          <p class={styles.error} id={errorId.value}>
            <span class={styles.glyph}>
              <Icon name="error" size="sm" />
            </span>
            {props.error}
          </p>
        ) : null}
      </div>
    )
  })
}
